-- ============================================================
-- SCA San Juan Bautista Peñolite — envío automático por peso (CEACERO)
-- Ejecutar completo en Supabase -> SQL Editor -> New query -> Run.
-- Se puede ejecutar más de una vez sin romper nada.
--
-- Qué crea:
--   1. Los pesos de las cajas en pricing_config (los lee el configurador).
--   2. tarifa_transporte: la tarifa de CEACERO y los parámetros (descuento,
--      carburante, IVA, margen, redondeo). PRIVADA: solo Eva con sesión.
--   3. envio_tarifas: el precio final al cliente por provincia y escalón de
--      peso, que publica el panel. PÚBLICA para lectura (la usa la web).
--   4. Carga la tarifa de CEACERO (origen Jaén, vigente desde 01/02/2026).
--
-- Después de ejecutarlo: Panel de Eva -> Envíos -> "Publicar precios".
-- Hasta que se publiquen, la web sigue usando los precios fijos antiguos.
-- ============================================================

-- 1) Pesos reales de cada caja cerrada y embalada
alter table public.pricing_config
  add column if not exists peso_caja_3x5l numeric not null default 13.74,
  add column if not exists peso_caja_6x2l numeric not null default 10.98;

-- 2) Tarifa del transportista + parámetros (privada)
create table if not exists public.tarifa_transporte (
  id int primary key default 1,
  transportista text not null default 'CEACERO',
  vigente_desde date,
  origen_cp int not null default 23,
  zonas jsonb not null,
  escalones jsonb not null,
  precios jsonb not null,
  limites_kg jsonb not null default '{}'::jsonb,
  descuento_pct numeric not null default 18.6,
  carburante_pct numeric not null default 4,
  iva_pct numeric not null default 21,
  margen_pct numeric not null default 0,
  redondeo_eur numeric not null default 0.10,
  publicado_at timestamptz,
  updated_at timestamptz not null default now(),
  constraint tarifa_una_sola_fila check (id = 1)
);

alter table public.tarifa_transporte enable row level security;

drop policy if exists "tarifa solo eva lee" on public.tarifa_transporte;
create policy "tarifa solo eva lee" on public.tarifa_transporte
  for select using (auth.role() = 'authenticated');

drop policy if exists "tarifa solo eva actualiza" on public.tarifa_transporte;
create policy "tarifa solo eva actualiza" on public.tarifa_transporte
  for update using (auth.role() = 'authenticated');

-- Recuerda: además de las políticas hacen falta los permisos base de
-- Postgres (si no, rechaza el acceso antes de mirar RLS). Aquí NO se da
-- ningún permiso a anon: la tarifa en bruto no debe ser pública.
grant select, update on public.tarifa_transporte to authenticated;

-- 3) Precio final al cliente por provincia y escalón de peso (pública)
create table if not exists public.envio_tarifas (
  provincia text not null,
  escalon_kg int not null,
  precio numeric not null,
  publicado_at timestamptz not null default now(),
  primary key (provincia, escalon_kg)
);

alter table public.envio_tarifas enable row level security;

drop policy if exists "envio_tarifas lectura publica" on public.envio_tarifas;
create policy "envio_tarifas lectura publica" on public.envio_tarifas
  for select using (true);

drop policy if exists "envio_tarifas eva inserta" on public.envio_tarifas;
create policy "envio_tarifas eva inserta" on public.envio_tarifas
  for insert with check (auth.role() = 'authenticated');

drop policy if exists "envio_tarifas eva actualiza" on public.envio_tarifas;
create policy "envio_tarifas eva actualiza" on public.envio_tarifas
  for update using (auth.role() = 'authenticated');

drop policy if exists "envio_tarifas eva borra" on public.envio_tarifas;
create policy "envio_tarifas eva borra" on public.envio_tarifas
  for delete using (auth.role() = 'authenticated');

grant select on public.envio_tarifas to anon, authenticated;
grant insert, update, delete on public.envio_tarifas to authenticated;

-- 4) Carga de la tarifa de CEACERO
-- Tarifa del transportista cargada con scripts/extraer-tarifa-ceacero.py
-- Se puede ejecutar varias veces: actualiza la tarifa sin tocar los parámetros
-- (descuento, carburante, IVA, margen, redondeo) que Eva ha configurado.
insert into public.tarifa_transporte (id, transportista, vigente_desde, origen_cp, zonas, escalones, precios, limites_kg)
select 1, 'CEACERO'::text, date '2026-02-01', t.origen_cp, t.zonas, t.escalones, t.precios, t.limites_kg
